Given the root of a binary tree, convert the binary tree to its Mirror tree.Note: Mirror of a Binary Tree T is another Binary Tree M(T) with left and right children of all non-leaf nodes interchanged.Examples:Input: root = [1, 2, 3, N, N, 4]Output: [1, 3, 2, N, 4]Explanation:  In the inverted tree, every non-leaf node has its left and right child interchanged.Input: root = [1, 2, 3, 4, 5]Output: [1, 3, 2, N, N, 5, 4]Explanation: In the inverted tree, every non-leaf node has its left and right child interchanged.Try It YourselfTable of ContentRecursive Approach - O(n) Time and O(n) SpaceIterative BFS using Queue - O(n) Time and O(n) SpaceRecursive Approach - O(n) Time and O(n) SpaceThe idea is to use recursion to traverse the tree in Post Order (left, right, root) and while traversing each node, swap the left and right subtrees.Working of Approach:Start from the root node.Recursively mirror the left subtree.Recursively mirror the right subtree.Swap the left and right child of the current node.Continue until all nodes are processed.
            C++

    #include <iostream>
#include <queue>
using namespace std;

class Node
{
  public:
    int data;
    Node *left, *right;

    Node(int x)
    {
        data = x;
        left = right = nullptr;
    }
};

// Function to convert binary tree into its mirror tree.
void mirror(Node *root)
{
    // Base case
    if (root == nullptr)
        return;

    // Mirror left subtree
    mirror(root->left);

    // Mirror right subtree
    mirror(root->right);

    // Swap left and right child
    swap(root->left, root->right);
}

void printLevelOrder(Node *root)
{
    if (!root)
    {
        cout << "[]";
        return;
    }

    vector<string> ans;
    queue<Node *> q;
    q.push(root);

    while (!q.empty())
    {
        Node *curr = q.front();
        q.pop();

        if (curr)
        {
            ans.push_back(to_string(curr->data));
            q.push(curr->left);
            q.push(curr->right);
        }
        else
        {
            ans.push_back("N");
        }
    }

    // Remove trailing nulls
    while (!ans.empty() && ans.back() == "N")
        ans.pop_back();

    cout << "[";
    for (int i = 0; i < ans.size(); i++)
    {
        cout << ans[i];
        if (i + 1 != ans.size())
            cout << ", ";
    }
    cout << "]";
}

int main()
{
    // root = [1, 2, 3, 4, 5]

    Node *root = new Node(1);
    root->left = new Node(2);
    root->right = new Node(3);
    root->left->left = new Node(4);
    root->left->right = new Node(5);

    mirror(root);
    printLevelOrder(root);

    return 0;
}


